209			t.Fatal("nil roles decoded as non-nil")
210		}
211		if back[3].Decision.Request.Subject.Roles == nil {
212			t.Fatal("empty roles decoded as nil")
213		}
214		if back[3].Decision.Decision.Matched == nil {
215			t.Fatal("empty matched list decoded as nil")
216		}
217	
218		// Three byte-different strings stay distinguishable: archives of
219		// one-byte-different reasons must themselves differ.
220		for _, pair := range [][2]string{
221			{invalidByte, anotherInvalidByte},
222			{invalidByte, replacementRune},
223			{anotherInvalidByte, replacementRune},
224		} {
225			oneRecs := singleStringRecords(t, "o", pair[0])
226			twoRecs := singleStringRecords(t, "o", pair[1])
227			one, err := EncodeAuditArchive("o", oneRecs,
228				Checkpoint{Org: "o", EndSeq: 1, Fingerprint: oneRecs[0].Fingerprint})
229			if err != nil {
230				t.Fatal(err)
231			}
232			two, err := EncodeAuditArchive("o", twoRecs,
233				Checkpoint{Org: "o", EndSeq: 1, Fingerprint: twoRecs[0].Fingerprint})
234			if err != nil {
235				t.Fatal(err)
236			}
237			if bytes.Equal(one, two) {
238				t.Fatalf("archive collapses byte-different reasons into identical bytes")
239			}
240			// And each must decode back to exactly its own raw reason.
241			if back, err := DecodeAuditArchive(one, "o",
242				Checkpoint{Org: "o", EndSeq: 1, Fingerprint: oneRecs[0].Fingerprint}); err != nil ||
243				back[0].Decision.Decision.Reason != pair[0] ||
244				back[0].Decision.Decision.Reason == pair[1] {
245				t.Fatalf("reason round trip = %q, err = %v", back[0].Decision.Decision.Reason, err)
246			}
247		}
248	}
