273		if b, err := EncodeAuditArchive("", recs, cp); !errors.Is(err, ErrMissingOrganization) || b != nil {
274			t.Fatalf("empty org: bytes=%v err=%v", b, err)
275		}
276	
277		bad := func(mutate func([]AuditRecord) []AuditRecord, checkpoint Checkpoint) {
278			t.Helper()
