527	// TestArchiveIsReadOnlyAndDetached proves encode and decode mutate nothing
528	// and return values independent of their inputs and of each other.
529	func TestArchiveIsReadOnlyAndDetached(t *testing.T) {
530		s := NewStore()
531		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
532		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
533		before, beforeCP, _ := s.AuditExport("acme", 0)
534	
535		recs, cp, _ := s.AuditExport("acme", 0)
536		snapshot := cloneExportedRecords(recs)
537		archive, err := EncodeAuditArchive("acme", recs, cp)
538		if err != nil {
539			t.Fatal(err)
540		}
541		if !reflect.DeepEqual(recs, snapshot) {
542			t.Fatal("encode mutated the supplied records")
543		}
544		// Encode/decode append nothing to any service state.
545		after, afterCP, _ := s.AuditExport("acme", 0)
546		if !reflect.DeepEqual(after, before) || afterCP != beforeCP {
547			t.Fatal("archive operations changed service state")
548		}
549	
550		got, err := DecodeAuditArchive(archive, "acme", cp)
551		if err != nil {
552			t.Fatal(err)
553		}
554		// Mutating the input bytes after decode cannot reach a prior result.
555		for i := range archive {
556			archive[i] = 0
557		}
558		if got[0].Change.Policies[0].ID != "p1" {
559			t.Fatal("decoded records alias the archive input bytes")
560		}
561		// Mutating one decoded result cannot affect a later decode.
562		got[0].Change.Policies[0].ID = "hacker"
563		got[1].Decision.Request.Subject.ID = "hacker"
564		got[1].Decision.Decision.Matched = append(got[1].Decision.Decision.Matched, "x")
565		fresh, err := EncodeAuditArchive("acme", recs, cp)
566		if err != nil {
567			t.Fatal(err)
568		}
569		again, err := DecodeAuditArchive(fresh, "acme", cp)
570		if err != nil {
571			t.Fatal(err)
572		}
573		if !reflect.DeepEqual(again, recs) {
574			t.Fatal("mutation of one decoded result reached another decode")
575		}
576	}
