578	// TestArchiveRoundTripAfterInstanceEnds simulates the stated lifecycle:
579	// export and archive on one instance, then (with no Store at all) read the
580	// bytes elsewhere and continue offline review against the retained
581	// checkpoint.
582	func TestArchiveRoundTripAfterInstanceEnds(t *testing.T) {
583		first := NewStore()
584		first.Publish("acme", 0, []Policy{
585			{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: " r 1 "},
586		})
587		original := first.Decide("acme", request("acme", "u1", " r 1 ", "org/a", "read"))
588		recs, cp, err := first.AuditExport("acme", 0)
589		if err != nil {
590			t.Fatal(err)
591		}
592		saved, err := EncodeAuditArchive("acme", recs, cp)
593		if err != nil {
594			t.Fatal(err)
595		}
596	
597		// New instance, no Store involved in decoding.
598		loaded, err := DecodeAuditArchive(saved, "acme", cp)
599		if err != nil {
600			t.Fatalf("read after instance end: %v", err)
601		}
602		review, err := RecheckDecisionOffline("acme", loaded, cp, 2)
603		if err != nil {
604			t.Fatal(err)
605		}
606		if !review.Consistent || !reflect.DeepEqual(review.Original, original) {
607			t.Fatalf("post-restart review = %+v, original %+v", review, original)
608		}
609	}
